/**
 * Debounce function implementation.
 *
 * @param {Function} func The function to be debounced.
 * @param {number} delay The time in milliseconds to wait after the last call before executing func.
 * @returns {Function} A new debounced version of the function.
 */
function debounce(func, delay) {
  let timeoutId; // Variable to hold the timer ID

  // Return the new function that will be called by the user
  return function(...args) {
    // 'this' context is preserved for the original function call
    const context = this;

    // 1. Clear the previous timer if it exists
    clearTimeout(timeoutId);

    // 2. Set a new timer
    timeoutId = setTimeout(() => {
      // 3. Execute the original function after the delay
      func.apply(context, args);
    }, delay);
  };
}

// --- Example Usage ---

// 1. The function we want to debounce (e.g., an expensive API call)
