debouncedSearch("a");
debouncedSearch("ap");
debouncedSearch("app");
debouncedSearch("appl");
debouncedSearch("apple"); // This is the last call

// After 500ms of silence, only this will execute:
setTimeout(() => {
    console.log("\n--- 500ms passed. Only the final call should execute. ---");
}, 1000);
```

