  const chunkedArray = [];

  for (let i = 0; i < array.length; i += n) {
    // Use slice to extract the portion from index i up to i + n
    const chunk = array.slice(i, i + n);
    chunkedArray.push(chunk);
  }

  return chunkedArray;
}

