 * Converts a temperature from Celsius to Fahrenheit, including input validation.
 *
 * @param {*} celsius The temperature value to convert.
 * @returns {number|string} The temperature in Fahrenheit, or an error message if input is invalid.
 */
function celsiusToFahrenheitValidated(celsius) {
  // 1. Check if the input is a valid finite number
  if (typeof celsius !== 'number' || !isFinite(celsius)) {
    return "Error: Input must be a valid number.";
  }

  // 2. Perform the conversion
  const fahrenheit = (celsius * 9/5) + 32;
  return fahrenheit;
}

