console.log("null:", validateEmailSimple(null)); // false
```

### Option 2: More Robust (Stricter RFC 5322 Compliance)

Email validation according to the official RFC standards is notoriously complex. A truly RFC-compliant regex is extremely long and often impractical. However, if you need a stricter check, you can use a more comprehensive pattern.

**Note:** This pattern is much more complex and might fail on some technically valid but unusual email formats.

```javascript
/**
 * Validates an email address using a more comprehensive (but still practical) regex.
 * @param {string} email The email string to validate.
 * @returns {boolean} True if the email format is valid, false otherwise.
 */
function validateEmailRobust(email) {
  if (typeof email !== 'string' || email.trim() === '') {
    return false;
  }

  // This regex attempts to cover most valid characters, including dots, hyphens, and subdomains.
  const emailRegex = new RegExp(
    /^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/
  );

  return emailRegex.test(String(email).toLowerCase());
}

