### The Throttling Function

```javascript
/**
 * Creates a throttled version of a function that only invokes it at most once
 * per every 'wait' milliseconds.
 *
 * @param {Function} func The function to throttle.
 * @param {number} wait The number of milliseconds to throttle invocations to.
 * @returns {Function} A new, throttled function.
 */
function throttle(func, wait) {
  let timeout = null;
  let lastArgs = null;
  let lastThis = null;
  let lastCallTime = 0;

  return function(...args) {
    const context = this;
    const now = Date.now();

    // 1. Check if we are within the cooldown period
    if (now - lastCallTime < wait) {
      // If it's too soon, store the latest arguments and context
      lastArgs = args;
      lastThis = context;
      // We don't call func yet, we just update the pending call
      return;
    }

    // 2. If the cooldown has passed, execute the function immediately
    if (timeout) {
      // If there's a pending timeout (from a previous call), clear it
      clearTimeout(timeout);
    }

    // Execute the function now
    func.apply(context, args);
    lastCallTime = now;

    // 3. Set a timeout to ensure the function doesn't run again too soon
    // (This is crucial for "leading edge" throttling)
    timeout = setTimeout(() => {
      timeout = null;
      lastArgs = null;
      lastThis = null;
    }, wait);
  };
}

// --- Example Usage ---

