Here is a comprehensive and well-explained TypeScript function to debounce another function.

This solution uses a common pattern involving `setTimeout` and a closure to manage the delay.

### TypeScript Debounce Function

```typescript
/**
 * Creates a debounced version of a function that delays invoking `func`
 * until after `wait` milliseconds have elapsed since the last time the
 * debounced function was invoked.
 *
 * @param func The function to debounce.
 * @param wait The number of milliseconds to wait after the last call.
 * @returns A new function that will be called only after `wait` milliseconds
 *          have passed without any new calls.
 */
function debounce<T extends (...args: any[]) => any>(
    func: T,
    wait: number
): (...args: Parameters<T>) => void {
    let timeoutId: ReturnType<typeof setTimeout> | null = null;

    // Return the debounced function
    return function(this: ThisParameterType<T>, ...args: Parameters<T>): void {
        // 1. Clear the previous timeout if it exists
        if (timeoutId !== null) {
            clearTimeout(timeoutId);
        }

        // 2. Set a new timeout
        timeoutId = setTimeout(() => {
            // 3. Execute the original function with the correct context and arguments
            func.apply(this, args);
            timeoutId = null; // Clear the ID after execution
        }, wait);
    };
}

// --- Example Usage ---

// 1. The function we want to debounce (e.g., an expensive API call or UI update)
function handleSearchInput(searchTerm: string): void {
    console.log(`[API Call] Searching for: "${searchTerm}"`);
}

// 2. Create the debounced version, waiting 500ms
