console.log("--- Starting Debounce Test ---");

// Simulate rapid user input (typing quickly)
console.log("Calling search rapidly...");
debouncedSearch("a");
debouncedSearch("ap");
debouncedSearch("app");
debouncedSearch("appl");
debouncedSearch("apple"); // This call will be the one that eventually trigger the function

// Wait a moment...
setTimeout(() => {
    console.log("\n--- Pausing for 1 second ---");
    // If we call it again here, it will reset the timer
    debouncedSearch("apple pie");
}, 1000);

// Wait another moment...
