### Option 1: Simple Approach (Splitting by Whitespace)

This is the most straightforward method. It splits the string by any sequence of whitespace characters and then filters out any empty strings that might result from multiple spaces.

```typescript
/**
 * Counts the number of words in a given string by splitting it by whitespace.
 * @param text The input string to analyze.
 * @returns The number of words in the string.
 */
function countWordsSimple(text: string): number {
  if (!text || text.trim() === "") {
    return 0;
  }

  // 1. Trim leading/trailing whitespace
  // 2. Split by one or more whitespace characters (\s+)
  // 3. Filter out any empty strings that might result (e.g., from multiple spaces)
  const words = text.trim().split(/\s+/).filter(word => word.length > 0);

  return words.length;
}

