/**
 * Computes the median of an array of numbers.
 *
 * The median is the middle value of a sorted dataset.
 * - If the array has an odd number of elements, the median is the middle element.
 * - If the array has an even number of elements, the median is the average of the two middle elements.
 *
 * @param numbers An array of numbers.
 * @returns The median of the array, or NaN if the input array is empty.
 */
function computeMedian(numbers: number[]): number {
    // 1. Handle edge case: Empty array
    if (numbers.length === 0) {
        console.error("Cannot compute the median of an empty array.");
        return NaN;
    }

    // 2. Sort the array numerically
    // We create a copy using the spread operator (...) to ensure the original array is not mutated.
    const sortedNumbers = [...numbers].sort((a, b) => a - b);

    const length = sortedNumbers.length;

    // 3. Determine if the length is odd or even
    if (length % 2 === 1) {
        // Odd length: The median is the element at the exact middle index.
        // Math.floor(length / 2) gives the correct middle index.
        const middleIndex = Math.floor(length / 2);
        return sortedNumbers[middleIndex];
    } else {
        // Even length: The median is the average of the two middle elements.
        // The two middle indices are (length / 2) - 1 and (length / 2).
        const upperMiddleIndex = length / 2;
        const lowerMiddleIndex = upperMiddleIndex - 1;

        const middle1 = sortedNumbers[lowerMiddleIndex];
        const middle2 = sortedNumbers[upperMiddleIndex];

        return (middle1 + middle2) / 2;
    }
}

