/**
 * A generic class representing a Stack data structure.
 * It follows the Last-In, First-Out (LIFO) principle.
 *
 * @template T The type of elements that the stack can hold.
 */
class Stack<T> {
    // Private array to store the stack elements.
    // Using a standard array is the most efficient way to implement a stack in JavaScript/TypeScript.
    private items: T[];

    /**
     * Initializes a new instance of the Stack class.
     */
    constructor() {
        this.items = [];
        console.log("Stack initialized.");
    }

    /**
     * Adds an element to the top of the stack.
     * @param element The element to be added to the stack.
     */
    public push(element: T): void {
        this.items.push(element);
        console.log(`Pushed: ${element}. Current stack: [${this.items.join(', ')}]`);
    }

    /**
     * Removes and returns the element at the top of the stack.
     * @returns The element that was removed from the top of the stack, or undefined if the stack is empty.
     */
    public pop(): T | undefined {
        if (this.isEmpty()) {
            console.warn("Error: Cannot pop from an empty stack.");
            return undefined;
        }
        // Array's pop() method removes the last element.
        const poppedItem = this.items.pop();
        console.log(`Popped: ${poppedItem}. Current stack: [${this.items.join(', ')}]`);
        return poppedItem;
    }

    /**
     * Returns the element at the top of the stack without removing it.
     * @returns The element at the top of the stack, or undefined if the stack is empty.
     */
    public peek(): T | undefined {
        if (this.isEmpty()) {
            console.warn("Error: Cannot peek into an empty stack.");
            return undefined;
        }
        // Access the last element without modifying the array.
        return this.items[this.items.length - 1];
    }

    /**
     * Checks if the stack is empty.
     * @returns True if the stack contains no elements, false otherwise.
     */
    public isEmpty(): boolean {
        return this.items.length === 0;
    }

    /**
     * Returns the current number of elements in the stack.
     * @returns The size of the stack.
     */
    public size(): number {
        return this.items.length;
    }
}

