This solution handles common edge cases like leading/trailing underscores and multiple consecutive underscores gracefully.

### TypeScript Implementation

```typescript
/**
 * Converts a string from snake_case to camelCase.
 *
 * Examples:
 * - "hello_world"      -> "helloWorld"
 * - "user_id_details"   -> "userIdDetails"
 * - "_leading_underscore" -> "leadingUnderscore"
 * - "trailing_underscore_" -> "trailingUnderscore"
 * - "multiple__underscores" -> "multipleUnderscores"
 * - "single"            -> "single"
 * - ""                  -> ""
 *
 * @param snakeCaseString The input string in snake_case format.
 * @returns The converted string in camelCase format.
 */
function snakeToCamel(snakeCaseString: string): string {
    if (!snakeCaseString) {
        return "";
    }

    // 1. Split the string by underscores.
    // 2. Filter out any empty strings that result from leading/trailing/multiple underscores.
    const parts = snakeCaseString
        .split('_')
        .filter(part => part.length > 0);

    if (parts.length === 0) {
        return "";
    }

    // 3. The first part remains entirely lowercase (or as is).
    let camelCaseString = parts[0];

    // 4. Iterate over the rest of the parts and capitalize the first letter of each.
    for (let i = 1; i < parts.length; i++) {
        const part = parts[i];
        if (part.length > 0) {
            // Capitalize the first letter and append the rest of the string (lowercased for safety)
            const capitalizedPart = part.charAt(0).toUpperCase() + part.slice(1);
            camelCaseString += capitalizedPart;
        }
    }

    return camelCaseString;
}

