This solution uses a **stack** (implemented with an array) which is the standard and most effective way to solve parenthesis balancing problems.

### TypeScript Implementation

```typescript
/**
 * Checks if the parentheses in a given string are balanced.
 * It handles three types of parentheses: (), [], and {}.
 *
 * @param str The input string to check.
 * @returns True if the parentheses are balanced, false otherwise.
 */
function areParenthesesBalanced(str: string): boolean {
    // 1. Initialize a stack to keep track of opening brackets.
    const stack: string[] = [];

    // 2. Define a map for quick lookup of corresponding closing brackets.
    const map: { [key: string]: string } = {
        ')': '(',
        ']': '[',
        '}': '{'
    };

    // 3. Define the set of opening brackets.
    const openingBrackets = new Set(['(', '[', '{']);

    // 4. Iterate through every character in the string.
    for (const char of str) {
        // Case 1: If the character is an opening bracket, push it onto the stack.
        if (openingBrackets.has(char)) {
            stack.push(char);
        } 
        // Case 2: If the character is a closing bracket.
        else if (map[char]) {
            // If the stack is empty, we have a closing bracket without a matching opener.
            if (stack.length === 0) {
                return false;
            }

            // Pop the top element from the stack.
            const lastOpen = stack.pop();

            // Check if the popped opening bracket matches the required opening bracket.
            if (lastOpen !== map[char]) {
                return false; // Mismatch found (e.g., found ']' but expected '(')
            }
        }
        // Ignore any other characters (letters, numbers, spaces, etc.)
    }

    // 5. Final check: If the stack is empty, all opening brackets were correctly closed.
    // If the stack is NOT empty, it means there are unclosed opening brackets left.
    return stack.length === 0;
}

// --- Examples ---

console.log(`"()[]{}" is balanced: ${areParenthesesBalanced("()[]{}")}`); // true
console.log(`"([{}])" is balanced: ${areParenthesesBalanced("([{}])")}`); // true
console.log(`"(]" is balanced: ${areParenthesesBalanced("(]")}`);       // false (Mismatch)
console.log(`"([)]" is balanced: ${areParenthesesBalanced("([)]")}`);     // false (Incorrect order)
console.log(`"{[}" is balanced: ${areParenthesesBalanced("{[}")}`);       // false (Unclosed)
console.log(`"{{}}" is balanced: ${areParenthesesBalanced("{{}}")}`);     // true
console.log(`"" is balanced: ${areParenthesesBalanced("")}`);             // true
console.log(`"abc(123)xyz" is balanced: ${areParenthesesBalanced("abc(123)xyz")}`); // true (Ignores non-bracket chars)
console.log(`"]" is balanced: ${areParenthesesBalanced("]")}`);           // false (Closing bracket first)
```

