### Rust Code

```rust
use std::f64;

/// Represents a point in a 2D Cartesian coordinate system.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Point {
    pub x: f64,
    pub y: f64,
}

impl Point {
    /// Creates a new Point.
    pub fn new(x: f64, y: f64) -> Self {
        Point { x, y }
    }

    /// Calculates the Euclidean distance between this point and another point.
    ///
    /// The distance formula is: sqrt((x2 - x1)^2 + (y2 - y1)^2)
    ///
    /// # Arguments
    ///
    /// * `other` - A reference to the other `Point` to calculate the distance to.
    ///
    /// # Returns
    ///
    /// The distance as an `f64`.
    pub fn distance_to(&self, other: &Point) -> f64 {
        let dx = other.x - self.x;
        let dy = other.y - self.y;

        // Calculate the square of the differences
        let dx_squared = dx * dx;
        let dy_squared = dy * dy;

        // Return the square root of the sum of the squares
        (dx_squared + dy_squared).sqrt()
    }
}

fn main() {
    // 1. Create two points
    let p1 = Point::new(1.0, 2.0);
    let p2 = Point::new(4.0, 6.0);

    println!("Point 1: {:?}", p1);
    println!("Point 2: {:?}", p2);

    // 2. Calculate the distance between them
    let dist = p1.distance_to(&p2);

    println!("\nThe distance between P1 and P2 is: {:.4}", dist);
    // Expected calculation: sqrt((4-1)^2 + (6-2)^2) = sqrt(3^2 + 4^2) = sqrt(9 + 16) = sqrt(25) = 5.0

    // Example 2: Another calculation
    let p3 = Point::new(0.0, 0.0);
    let p4 = Point::new(3.0, 4.0);
    let dist2 = p3.distance_to(&p4);
    println!("\nThe distance between P3(0,0) and P4(3,4) is: {:.4}", dist2);
    // Expected calculation: sqrt(3^2 + 4^2) = 5.0
}
```

